### 2. Complete Source Code

#### A. Kernel Modifications
```c
// kernel/fs.h
struct inode_info { uint type; short major; short minor; short nlink; uint size; uint addrs[13]; };

// kernel/sysfile.c
uint64 sys_get_dinode(void) {
  int inum; uint64 addr;
  struct buf *bp; struct dinode *dip;
  if(argint(0, &inum) < 0 || argaddr(1, &addr) < 0) return -1;
  bp = bread(1, IBLOCK(inum, sb));
  dip = (struct dinode*)bp->data + (inum % IPB);
  struct inode_info info;
  info.type = dip->type; info.nlink = dip->nlink; 
  info.size = dip->size; memmove(info.addrs, dip->addrs, sizeof(info.addrs));
  brelse(bp);
  return copyout(myproc()->pagetable, addr, (char *)&info, sizeof(info));
}
```

