### 1. Design Document (Requirements 1 & 3)

**Purpose:** Develop a suite of tools to inspect and recover a damaged xv6-riscv file system, specifically addressing directory corruption and orphaned inodes.

**Design Architecture:**
- **Kernel Layer:** A new system call `get_dinode(inum, struct inode_info*)` is added to allow user-level tools to read raw disk inodes, bypass the file system's standard safety checks, and identify corrupted metadata.
- **Inspection Layer (C Tools):** 
    - `imapWalker`: Scans the inode table to identify allocated vs. free inodes.
    - `inodeReader`: Dumps blocks and metadata for a specific inode.
    - `directoryWalker`: Recursively traverses the directory tree to identify reachable inodes.
- **Recovery Layer (Python):** An external tool `recovery_suite.py` that parses the `fs.img` directly. It performs a cross-reference between the inode table and the directory tree to identify orphaned inodes (allocated but unreachable) and broken links (directory entries pointing to invalid inodes).

### 2. Missing User-Level Tool: `user/directoryWalker.c` (Requirement 2.2)

```c
#include "kernel/types.h"
#include "kernel/stat.h"
#include "user/user.h"
#include "kernel/fs.h"

void walk(char *path) {
  char buf[512], *p;
  int fd;
  struct dirent de;
  struct stat st;

  if((fd = open(path, 0)) < 0) return;
  if(fstat(fd, &st) < 0 || st.type != T_DIR) {
    close(fd); return;
  }

  if(strlen(path) + 1 + DIRSIZ + 1 > sizeof buf) return;
  strcpy(buf, path);
  p = buf+strlen(buf);
  if(p > buf && p[-1] != '/') *p++ = '/';

  while(read(fd, &de, sizeof(de)) == sizeof(de)){
    if(de.inum == 0 || strcmp(de.name, ".") == 0 || strcmp(de.name, "..") == 0) continue;
    memmove(p, de.name, DIRSIZ);
    p[DIRSIZ] = 0;
    if(stat(buf, &st) < 0) continue;
    printf("Path: %-20s | Inode: %d | Type: %d\n", buf, de.inum, st.type);
    if(st.type == T_DIR) walk(buf);
  }
  close(fd);
}

int main(int argc, char *argv[]) {
  if(argc < 2) walk("/");
  else walk(argv[1]);
  exit(0);
}
```

### 3. Final Recovery Suite (Python)
This script is the primary tool for Requirement 6 (Repair). It performs a reachability analysis to detect the four specific corruption scenarios (a, b, c, d).

```python
import struct
import sys
import os

# xv6 Constants
BSIZE = 1024
IPB = BSIZE // 64 
DIRSIZ = 14
ROOTINO = 1

class XV6RecoverySuite:
    def __init__(self, image_path):
        self.image_path = image_path
        if not os.path.exists(image_path):
            print(f"Error: {image_path} not found.")
            sys.exit(1)
        self.f = open(image_path, "rb+")
        self.read_superblock()

    def read_superblock(self):
        self.f.seek(BSIZE)
        sb = struct.unpack("<IIIIIIII", self.f.read(32))
        self.ninodes = sb[3]
        self.inodestart = sb[6]

    def get_inode(self, inum):
        offset = (self.inodestart * BSIZE) + (inum * 64)
        self.f.seek(offset)
        data = self.f.read(64)
        res = struct.unpack("<hhhhI13I", data)
        return {"inum": inum, "type": res[0], "nlink": res[3], "size": res[4], "addrs": res[5:]}

    def get_dir_entries(self, inode):
        if inode['type'] != 1: return [] 
        entries = []
        for addr in inode['addrs'][:12]: # Direct blocks
            if addr == 0: continue
            self.f.seek(addr * BSIZE)
            block = self.f.read(BSIZE)
            for i in range(0, BSIZE, 16):
                inum, name = struct.unpack("<H14s", block[i:i+16])
                name = name.decode('ascii', errors='ignore').strip('\x00')
                if inum != 0: entries.append((inum, name))
        return entries

    def repair_analysis(self):
        print("\n=== FS REPAIR ANALYSIS REPORT ===")
        allocated = {i: self.get_inode(i) for i in range(1, self.ninodes) if self.get_inode(i)['type'] != 0}
        reachable = set()
        broken_links = []

        def walk(inum, path=""):
            if inum in reachable: return
            reachable.add(inum)
            ino = self.get_inode(inum)
            if ino['type'] == 1:
                entries = self.get_dir_entries(ino)
                if not entries and ino['size'] > 0:
                    print(f"[!] Scenario A Detected: Directory file at '{path}' (Inum {inum}) is corrupted/empty.")
                for cinum, name in entries:
                    if name in [".", ".."]: continue
                    child_ino = self.get_inode(cinum)
                    if child_ino['type'] == 0: broken_links.append((path + "/" + name, cinum))
                    else: walk(cinum, path + "/" + name)

        walk(ROOTINO, "")
        orphans = set(allocated.keys()) - reachable
        if broken_links:
            print(f"[!] Scenario B/C Detected: {len(broken_links)} directory entries point to corrupted inodes.")
            for path, inum in broken_links: print(f"    -> Broken Link: {path} points to Inode {inum} (Metadata Erased)")
        if orphans:
            print(f"[!] Orphans Found: {len(orphans)} inodes are allocated but unreachable.")
            for o in orphans: print(f"    -> Orphaned Inode {o} (Type: {allocated[o]['type']}, Size: {allocated[o]['size']})")
            print("\nREPAIR SUGGESTION: Create entries in /lost+found for orphaned inodes.")
        if not orphans and not broken_links: print("SUCCESS: No corruption detected in directory tree or inode table.")

if __name__ == "__main__":
    suite = XV6RecoverySuite("fs.img")
    suite.repair_analysis()
```

