import struct, sys, os

class XV6Recovery:
    def __init__(self, img_path):
        self.f = open(img_path, "rb+")
        self.f.seek(1024)
        sb = struct.unpack("<IIIIIIII", self.f.read(32))
        self.ninodes, self.inodestart = sb[3], sb[6]

    def get_inode(self, inum):
        self.f.seek((self.inodestart * 1024) + (inum * 64))
        d = struct.unpack("<hhhhI13I", self.f.read(64))
        return {"inum": inum, "type": d[0], "nlink": d[3], "size": d[4], "addrs": d[5:]}

    def corrupt(self, inum, target="inode"):
        self.f.seek((self.inodestart * 1024) + (inum * 64))
        self.f.write(b'\x00' * 64)
        print(f"Corrupted {target} {inum}")

    def repair_analysis(self):
        print("\n=== REPAIR ANALYSIS ===")
        allocated = {i: self.get_inode(i) for i in range(1, self.ninodes) if self.get_inode(i)['type'] != 0}
        reachable = set()
        def walk(inum):
            if inum in reachable: return
            reachable.add(inum)
            ino = self.get_inode(inum)
            if ino['type'] == 1:
                for addr in ino['addrs'][:12]:
                    if addr == 0: continue
                    self.f.seek(addr * 1024)
                    block = self.f.read(1024)
                    for i in range(0, 1024, 16):
                        c_inum, name = struct.unpack("<H14s", block[i:i+16])
                        if c_inum != 0 and name.strip(b'\x00') not in [b'.', b'..']: walk(c_inum)
        walk(1)
        orphans = set(allocated.keys()) - reachable
        for o in orphans: print(f"[!] Orphaned Inode {o} (Type: {allocated[o]['type']}) detected.")

