public class LATCalculator {

    public static void main(String[] args) {
        // Example 3-bit S-box: [7, 4, 5, 3, 0, 1, 2, 6]
        int[] sbox = {7, 4, 5, 3, 0, 1, 2, 6};
        int n = 3; 

        System.out.println("Calculating Linear Approximation Table...");
        int[][] lat = calculateLAT(sbox, n);

        displayAndValidate(lat, n);
    }

    /**
     * Calculates the LAT for a given S-box.
     */
    public static int[][] calculateLAT(int[] sbox, int n) {
        int size = 1 << n;
        int[][] lat = new int[size][size];
        int halfSize = size / 2;

        for (int a = 0; a < size; a++) { // Input mask
            for (int b = 0; b < size; b++) { // Output mask
                int matches = 0;
                for (int x = 0; x < size; x++) {
                    // Compute dot product parity: (a . x) and (b . S(x))
                    int inputParity = Integer.bitCount(a & x) % 2;
                    int outputParity = Integer.bitCount(b & sbox[x]) % 2;

                    if (inputParity == outputParity) {
                        matches++;
                    }
                }
                // Normalize: matches - 2^(n-1)
                lat[a][b] = matches - halfSize;
            }
        }
        return lat;
    }

    public static void displayAndValidate(int[][] lat, int n) {
