        boolean test1 = (lat[0][0] == expectedZeroMask);
        System.out.println("Test 1: LAT[0][0] matches 2^(n-1) -> " + (test1 ? "PASS" : "FAIL"));

        boolean test2 = true;
        for (int i = 1; i < size; i++) {
            if (lat[0][i] != 0 || lat[i][0] != 0) {
                test2 = false;
                break;
            }
        }
        System.out.println("Test 2: Zero-mask row/column property -> " + (test2 ? "PASS" : "FAIL"));
    }
}
