        int[] sbox = {6, 5, 1, 0, 3, 2, 7, 4};
        int[][] nlat = new int[8][8];

        // Calculate NLAT entries using bitwise dot product parity
        for (int a = 0; a < 8; a++) {
            for (int b = 0; b < 8; b++) {
