To provide a complete and functional solution in C++ as requested, I have implemented the Selection Sort algorithm, the logic to construct a balanced Binary Search Tree (BST) from the sorted data, and the performance measurement using the `<chrono>` library.

### Implementation Logic:
1.  **Selection Sort**: This algorithm sorts the array in $O(n^2)$ time by repeatedly finding the minimum element from the unsorted portion.
2.  **Balanced BST Construction**: To prevent the BST from becoming a degenerate tree (like a linked list), we sort the array first and then recursively pick the middle element as the root. This ensures the tree height is $O(\log n)$.
3.  **Time Measurement**: We use `std::chrono::high_resolution_clock` to measure the execution time of the sorting and tree construction processes.

```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <algorithm>

/**
 * Node structure for the Binary Search Tree.
 */
struct Node {
    int data;
    Node* left;
    Node* right;

    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

/**
 * Selection Sort Algorithm: O(n^2)
 * Repeatedly finds the minimum element and moves it to the front.
 */
void selectionSort(std::vector<int>& arr) {
    int n = arr.size();
    for (int i = 0; i < n - 1; i++) {
        int min_idx = i;
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[min_idx]) {
                min_idx = j;
            }
        }
        std::swap(arr[i], arr[min_idx]);
    }
}

/**
 * Constructs a Balanced BST from a sorted array.
 */
Node* sortedArrayToBST(const std::vector<int>& arr, int start, int end) {
    if (start > end) return nullptr;

    // Middle element becomes the root to ensure balance
    int mid = start + (end - start) / 2;
    Node* node = new Node(arr[mid]);

    // Recursively build left and right subtrees
    node->left = sortedArrayToBST(arr, start, mid - 1);
    node->right = sortedArrayToBST(arr, mid + 1, end);

    return node;
}

/**
 * Helper function for In-order traversal to verify the tree.
 */
void printInOrder(Node* node) {
    if (node == nullptr) return;
    printInOrder(node->left);
    std::cout << node->data << " ";
    printInOrder(node->right);
}

int main() {
    // Sample input data
    std::vector<int> data = {64, 34, 25, 12, 22, 11, 90};

    std::cout << "Original data: ";
    for (int x : data) std::cout << x << " ";
    std::cout << std::endl;

    // Start timing the selection sort and BST construction
    auto start = std::chrono::high_resolution_clock::now();

    // 1. Selection Sort
    selectionSort(data);

    // 2. Construct BST from the sorted array
    Node* root = sortedArrayToBST(data, 0, data.size() - 1);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

    // Output results
    std::cout << "Sorted data: ";
    for (int x : data) std::cout << x << " ";

    std::cout << "\nBST In-order verification: ";
    printInOrder(root);

    std::cout << "\n\nTotal running time (Sort + BST Construction): " 
              << duration.count() << " microseconds" << std::endl;

    return 0;
}
```

