// 1. BASE CLASS & 3. ENCAPSULATION
class Exhibit {
protected:
    std::string name;
    int year;

public:
    Exhibit(std::string n, int y) : name(n), year(y) {}
    virtual ~Exhibit() = default;

    std::string getName() const { return name; }
    int getYear() const { return year; }

    // 5. POLYMORPHISM
    virtual void display() const = 0;

    // 6. OPERATION OVERLOADING: Combining exhibit names
    std::string operator+(const Exhibit& other) const {
        return this->name + " & " + other.name;
    }
};

// 2. CLASSES & 4. INHERITANCE
class Painting : public Exhibit {
private:
    std::string artist;
public:
    Painting(std::string n, int y, std::string a) : Exhibit(n, y), artist(a) {}
    void display() const override {
        std::cout << "[Painting] '" << name << "' by " << artist << " (" << year << ")" << std::endl;
    }
};

class Sculpture : public Exhibit {
private:
    std::string material;
public:
    Sculpture(std::string n, int y, std::string m) : Exhibit(n, y), material(m) {}
    void display() const override {
        std::cout << "[Sculpture] '" << name << "' made of " << material << " (" << year << ")" << std::endl;
    }
};

class HistoricalArtifact : public Exhibit {
private:
    std::string origin;
public:
    HistoricalArtifact(std::string n, int y, std::string o) : Exhibit(n, y), origin(o) {}
    void display() const override {
        std::cout << "[Artifact] '" << name << "' from " << origin << " (" << year << ")" << std::endl;
    }
};

// 7. TEMPLATES & 8. STL LIBRARY
template <typename T>
class MuseumCollection {
private:
    std::vector<T*> items; // Encapsulation with STL vector

public:
    ~MuseumCollection() {
        for (auto item : items) delete item;
    }

    // 6. METHOD OVERLOADING: Add with or without priority
    void addExhibit(T* item) {
        items.push_back(item);
    }

    void addExhibit(T* item, bool priority) {
        if (priority) items.insert(items.begin(), item);
        else items.push_back(item);
    }

    // 1. DATA ANALYSIS AND PROCESSING
    void performAnalysis() const {
        if (items.empty()) return;

        double totalYear = 0;
        std::map<std::string, int> typeCounts; // STL Map for categorization

        for (const auto& item : items) {
            totalYear += item->getYear();
            typeCounts[typeid(*item).name()]++;
        }

        std::cout << "\n--- Data Analysis Report ---" << std::endl;
        std::cout << "Total Exhibits: " << items.size() << std::endl;
        std::cout << "Average Production Year: " << (totalYear / items.size()) << std::endl;
        std::cout << "Type Distribution:" << std::endl;
        for (auto const& [type, count] : typeCounts) {
            std::cout << " - " << type << ": " << count << std::endl;
        }
        std::cout << "----------------------------\n" << std::endl;
    }

    void showAll() const {
        for (const auto& item : items) {
            item->display(); // Polymorphic call
        }
    }
};

// --- MAIN EXECUTION ---
int main() {
    // 9. AT LEAST 5 CLASSES: Exhibit, Painting, Sculpture, HistoricalArtifact, MuseumCollection
    MuseumCollection<Exhibit> museum;

    // Adding items (Demonstrating Method Overloading)
    museum.addExhibit(new Painting("The Starry Night", 1889, "Vincent van Gogh"));
    museum.addExhibit(new Sculpture("David", 1504, "Marble"));
    museum.addExhibit(new HistoricalArtifact("Rosetta Stone", -196, "Egypt"), true); // Priority add

    std::cout << "Current Museum Exhibits:" << std::endl;
    museum.showAll();

    // Data Analysis and Processing
    museum.performAnalysis();

    // Operation Overloading
    Painting p("Mona Lisa", 1503, "Da Vinci");
    Sculpture s("Pieta", 1499, "Marble");
    std::cout << "Operator Overloading (+) Result: " << (p + s) << std::endl;

    return 0;
}
