function drawHexBin(canvasId, pData, color) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const center = 70;
    const radius = 55;
    const sides = 6;

    // Data mapping: Normalize stats to a 0.0 - 1.0 scale
    const values = [
        pData.score / 10,           // Score (Max 10)
        pData.hp / 100,             // HP (Max 100)
        pData.hits / 15,            // Ball Hits (Estimated max 15)
        pData.items / 5,            // Items (Estimated max 5)
        pData.oppHits / 10,         // Times hit opponent
        0.7                         // Consistency (Static filler)
    ];

    ctx.clearRect(0, 0, 140, 140);

    // Draw Background Hexagon
    ctx.strokeStyle = '#333';
    ctx.beginPath();
    for(let i=0; i<sides; i++) {
        let x = center + radius * Math.cos(i * 2 * Math.PI / sides);
        let y = center + radius * Math.sin(i * 2 * Math.PI / sides);
        ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.stroke();

    // Draw Dynamic Data Shape
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.6;
    ctx.beginPath();
    for(let i=0; i<sides; i++) {
        let val = Math.min(values[i], 1.0); // Cap at 100%
        let x = center + (radius * val) * Math.cos(i * 2 * Math.PI / sides);
        let y = center + (radius * val) * Math.sin(i * 2 * Math.PI / sides);
        ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
}

