```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <string>

using namespace std;

typedef long long ll;
typedef __int128_t int128;

const ll INF_LL = 1e18;

struct Edge {
    int to;
    ll w;
};

void dijkstra(int s, int n, const vector<vector<Edge>>& adj, vector<ll>& dist) {
    dist.assign(n + 1, INF_LL);
    dist[s] = 0;
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
    pq.push({0, s});
    while (!pq.empty()) {
        ll d = pq.top().first;
        int u = pq.top().second;
        pq.pop();
        if (d > dist[u]) continue;
        for (auto& e : adj[u]) {
            if (dist[u] + e.w < dist[e.to]) {
                dist[e.to] = dist[u] + e.w;
                pq.push({dist[e.to], e.to});
            }
        }
    }
}

struct Query {
    ll a, b;
    int id;
};

struct Line {
    ll d1, dn;
    int128 eval(const Query& q) const {
        return (int128)d1 * q.a - (int128)dn * q.b;
    }
};

struct LiChao {
    int n;
    vector<Line> tree;
    vector<bool> has;
    const vector<Query>& s_queries;
    bool is_min;

    LiChao(int _n, const vector<Query>& _queries, bool _is_min) 
        : n(_n), s_queries(_queries), is_min(_is_min) {
        tree.resize(4 * n + 1);
        has.assign(4 * n + 1, false);
    }

    void add(int node, int l, int r, Line nl) {
        if (!has[node]) {
            tree[node] = nl;
            has[node] = true;
            return;
        }
        int mid = l + (r - l) / 2;
        int128 new_m = nl.eval(s_queries[mid]), cur_m = tree[node].eval(s_queries[mid]);
        bool b_mid = is_min ? (new_m < cur_m) : (new_m > cur_m);
        if (b_mid) swap(tree[node], nl);
        if (l == r) return;
        int128 new_l = nl.eval(s_queries[l]), cur_l = tree[node].eval(s_queries[l]);
        bool b_l = is_min ? (new_l < cur_l) : (new_l > cur_l);
        if (b_l) add(2 * node, l, mid, nl);
        else add(2 * node + 1, mid + 1, r, nl);
    }

    int128 query(int node, int l, int r, int x) {
        if (!has[node]) return is_min ? (int128)2e35 : (int128)-2e35;
        int128 res = tree[node].eval(s_queries[x]);
        if (l == r) return res;
        int mid = l + (r - l) / 2;
        if (x <= mid) {
            int128 val = query(2 * node, l, mid, x);
            res = is_min ? min(res, val) : max(res, val);
        } else {
            int128 val = query(2 * node + 1, mid + 1, r, x);
            res = is_min ? min(res, val) : max(res, val);
        }
        return res;
    }
};

void print_int128(int128 n) {
    if (n == 0) { cout << "0\n"; return; }
    if (n < 0) { cout << "-"; n = -n; }
    string s;
    while (n > 0) {
        s += (char)('0' + (ll)(n % 10));
        n /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s << "\n";
}

