    vector<Query> s_queries = queries;
    sort(s_queries.begin(), s_queries.end(), [](const Query& x, const Query& y) {
        return (int128)x.a * y.b < (int128)y.a * x.b;
    });

    LiChao t_min(k, s_queries, true);
    LiChao t_max(k, s_queries, false);

    for (int i = 1; i <= n; ++i) {
        if (d1[i] != INF_LL && dn[i] != INF_LL) {
            t_min.add(1, 0, k - 1, {d1[i], dn[i]});
            t_max.add(1, 0, k - 1, {d1[i], dn[i]});
        }
    }

    vector<int128> results(k);
    for (int i = 0; i < k; ++i) {
        int128 v1 = t_min.query(1, 0, k - 1, i);
        int128 v2 = t_max.query(1, 0, k - 1, i);
        int128 a1 = (v1 < 0 ? -v1 : v1);
        int128 a2 = (v2 < 0 ? -v2 : v2);
        results[s_queries[i].id] = min(a1, a2);
    }

    for (int i = 0; i < k; ++i) {
        print_int128(results[i]);
    }

    return 0;
}
