### 4. Python Implementation: Multi-Threaded Socket Server
If you stick with sockets, your Raspberry Pi should handle concurrent connections to stay responsive. This script uses `threading` to ensure the server doesn't block.

```python
import socket
import threading
import subprocess
import logging

HOST, PORT = '0.0.0.0', 5000
COMMAND_MAP = {
    "UP": ["python3", "/home/pi/motor.py", "up"],
    "DOWN": ["python3", "/home/pi/motor.py", "down"],
}

logging.basicConfig(level=logging.INFO, format='%(threadName)s: %(message)s')

def handle_client(conn, addr):
    try:
        with conn:
            data = conn.recv(1024).decode('utf-8').strip().upper()
            if data in COMMAND_MAP:
                subprocess.run(COMMAND_MAP[data], check=True)
                conn.sendall(b"ACK")
            else:
                conn.sendall(b"ERR")
    except Exception as e:
        logging.error(f"Error: {e}")

def start_server():
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        s.bind((HOST, PORT))
        s.listen()
        while True:
            conn, addr = s.accept()
            threading.Thread(target=handle_client, args=(conn, addr)).start()

if __name__ == "__main__":
    start_server()
```

