To fulfill your request, I have rewritten the **Source-Vortex Panel Method** (Hess-Smith Method) in **MATLAB**. 

This script reads geometry from a file, prompts for flow conditions, performs a convergence study for accuracy, and compares results with analytical solutions for a cylinder (the standard benchmark for this method).

```matlab
% --- 2-D Source-Vortex Panel Method Solver (MATLAB) ---
% This script implements the Hess-Smith panel method to calculate 
% pressure distributions and lift on 2D geometries.

clear; clc; close all;

%% 1. Input Geometry
filename = 'geom.txt';
if exist(filename, 'file')
    data = load(filename);
    x_pts = data(:, 1);
    y_pts = data(:, 2);
else
    fprintf('File %s not found. Generating a default cylinder...\n', filename);
    theta = linspace(0, 2*pi, 101)';
    x_pts = 0.5 * cos(theta);
    y_pts = 0.5 * sin(theta);
    data = [x_pts, y_pts];
    save(filename, 'data', '-ascii');
end

%% 2. Flow Conditions
V_inf = input('Enter Free Stream Velocity (m/s) [default 1.0]: ');
if isempty(V_inf); V_inf = 1.0; end

alpha_deg = input('Enter Angle of Attack (degrees) [default 0.0]: ');
if isempty(alpha_deg); alpha_deg = 0.0; end
alpha = deg2rad(alpha_deg);

%% 3. Accuracy Check (Convergence Study)
fprintf('\n--- Accuracy Check (Convergence) ---\n');
resolutions = [10, 20, 40, 80, 160];
cl_history = zeros(length(resolutions), 1);

for k = 1:length(resolutions)
    N = resolutions(k);
    % Interpolate geometry to check different panel counts
    t_orig = linspace(0, 1, length(x_pts));
    t_new = linspace(0, 1, N+1);
    xi = interp1(t_orig, x_pts, t_new, 'linear')';
    yi = interp1(t_orig, y_pts, t_new, 'linear')';

    [~, ~, cl_history(k)] = solve_panel_method(xi, yi, V_inf, alpha);
    fprintf('Panels: %3d | Cl: %8.4f\n', N, cl_history(k));
end

%% 4. Final Solution and Comparison
[xc, cp, cl] = solve_panel_method(x_pts, y_pts, V_inf, alpha);

% Analytical Comparison (Cylinder Case)
% For a cylinder, Cp = 1 - 4*sin(theta)^2 and Cl = 0
theta_analytical = linspace(0, 2*pi, 200);
cp_analytical = 1 - 4*(sin(theta_analytical - alpha)).^2;
cl_analytical = 0;

% Report Lift Comparison
fprintf('\n--- Lift Coefficient Comparison ---\n');
fprintf('Numerical Cl:    %8.4f\n', cl);
if abs(max(x_pts) - min(x_pts) - 1.0) < 0.1
    fprintf('Analytical Cl:   %8.4f (Cylinder)\n', cl_analytical);
    fprintf('Absolute Error:  %8.4e\n', abs(cl - cl_analytical));
else
    % For airfoil (approximate comparison)
    cl_theory = 2 * pi * sin(alpha);
    fprintf('Thin Airfoil Theory Cl: %8.4f (Approx for airfoils)\n', cl_theory);
end

% Plotting Results
figure('Color', 'w', 'Name', 'Panel Method Results');

% Subplot 1: Geometry
subplot(2,1,1);
plot(x_pts, y_pts, 'k-o', 'MarkerFaceColor', 'r');
axis equal; grid on;
title('Panel Geometry');
xlabel('x'); ylabel('y');

% Subplot 2: Pressure Coefficient
subplot(2,1,2);
plot(xc, cp, 'rs-', 'LineWidth', 1.5, 'DisplayName', 'Numerical (Panel Method)');
hold on;
% If geometry is roughly circular, plot analytical cylinder solution
if abs(max(x_pts) - min(x_pts) - 1.0) < 0.1
    plot(0.5*cos(theta_analytical), cp_analytical, 'k--', 'DisplayName', 'Analytical (Cylinder)');
end
set(gca, 'YDir', 'reverse'); % Standard aero convention
grid on;
xlabel('x-coordinate');
ylabel('C_p');
title(['Pressure Coefficient Distribution (C_l = ', num2str(cl, '%.4f'), ')']);
legend show;

%% --- Solver Function ---
function [xc, cp, cl] = solve_panel_method(x, y, V_inf, alpha)
    num_pts = length(x);
    num_panels = num_pts - 1;

    % Pre-allocate
    xc = zeros(num_panels, 1);
    yc = zeros(num_panels, 1);
    S = zeros(num_panels, 1);
    phi = zeros(num_panels, 1);
    beta = zeros(num_panels, 1);

    for i = 1:num_panels
        xc(i) = (x(i) + x(i+1)) / 2;
        yc(i) = (y(i) + y(i+1)) / 2;
        dx = x(i+1) - x(i);
        dy = y(i+1) - y(i);
        S(i) = sqrt(dx^2 + dy^2);
        phi(i) = atan2(dy, dx);
        beta(i) = phi(i) + pi/2 - alpha;
    end

    % Influence Matrices
    A = zeros(num_panels + 1, num_panels + 1);
    B = zeros(num_panels, num_panels);

    for i = 1:num_panels
        for j = 1:num_panels
            if i == j
                A(i, j) = 0.5;
                B(i, j) = 0;
            else
                % Local coordinates
                dx = xc(i) - x(j);
                dy = yc(i) - y(j);
                x_loc = dx * cos(phi(j)) + dy * sin(phi(j));
                y_loc = -dx * sin(phi(j)) + dy * cos(phi(j));

                r1 = x_loc^2 + y_loc^2;
                r2 = (x_loc - S(j))^2 + y_loc^2;
                th1 = atan2(y_loc, x_loc);
                th2 = atan2(y_loc, x_loc - S(j));

                % Source influence
                f_src_n = 0.5/(2*pi) * log(r1/r2);
                f_src_t = (th2 - th1)/(2*pi);

                % Transform to global normal/tangent
                A(i, j) = f_src_n * cos(phi(i)-phi(j)) + f_src_t * sin(phi(i)-phi(j));
                B(i, j) = -f_src_n * sin(phi(i)-phi(j)) + f_src_t * cos(phi(i)-phi(j));
            end
        end
        % Vortex influence (sum of tangential effects)
        A(i, end) = -sum(B(i, 1:num_panels));
    end

    % Kutta Condition (Flow leaves trailing edge smoothly)
    A(end, 1) = 1;
    A(end, num_panels) = 1;
    A(end, end) = 0;

    % RHS
    rhs = -V_inf * cos(beta);
    rhs(end + 1) = 0;

    % Solve
    res = A \ rhs;
    lambdas = res(1:end-1);
    gamma = res(end);

    % Velocities and Cp
    Vt = zeros(num_panels, 1);
    for i = 1:num_panels
        term1 = V_inf * sin(beta(i));
        term2 = sum(lambdas .* B(i, :)');
        term3 = gamma * sum(A(i, 1:num_panels));
        Vt(i) = term1 + term2 + term3;
    end

    cp = 1 - (Vt ./ V_inf).^2;

    % Lift via Kutta-Joukowski
    chord = max(x) - min(x);
    total_gamma = gamma * sum(S);
    cl = (2 * total_gamma) / (V_inf * chord);
end
```

### Key Features of this Implementation:

1.  **Hess-Smith Logic**: It uses a combination of source panels and a constant vortex strength across all panels to satisfy the Kutta condition and calculate lift.
2.  **Kutta Condition**: The matrix system enforces that tangential velocities at the trailing edge are balanced, allowing for physical lift calculation.
3.  **Accuracy/Convergence**: The script includes a convergence study that interpolates geometry for different panel counts (10 to 160) and reports $C_l$ for each.
4.  **Analytical Comparison**: 
    *   **Pressure ($C_p$)**: For circular geometries, the code plots the analytical $C_p$ distribution against the numerical results.
    *   **Lift ($C_l$)**: The code explicitly reports the numerical $C_l$ in the command window and compares it to the analytical value (0 for a cylinder) to evaluate accuracy.
5.  **Input/Output**: It reads `geom.txt` (or generates a cylinder if missing) and prompts the user for $V_\infty$ and $\alpha$ using MATLAB's `input` function.

