 */
struct Synapse {
    IzhikevichNeuron* target;
    double weight;
    double last_pre_spike = -100.0;
    double last_post_spike = -100.0;
    const double tau_stdp = 20.0;    // Time constant for STDP (ms)
    const double learning_rate = 0.01;

    Synapse(IzhikevichNeuron* t, double w) : target(t), weight(w) {}

    /**
     * @brief Updates synaptic weight based on spike timing causality.
     */
    void update_weight(double t, bool is_pre_spike) {
        if (is_pre_spike) {
            last_pre_spike = t;
            double dt = last_pre_spike - last_post_spike;
            // Long-term depression if pre-spike follows post-spike
            weight -= learning_rate * std::exp(-std::abs(dt) / tau_stdp);
        } else {
            last_post_spike = t;
            double dt = last_post_spike - last_pre_spike;
            // Long-term potentiation if post-spike follows pre-spike
            weight += learning_rate * std::exp(-std::abs(dt) / tau_stdp);
        }
        // Enforce biological bounds
        weight = std::max(0.0, std::min(2.0, weight));
    }
};

/**
 * @brief Izhikevich Neuron class with dynamic connectivity and STDP.
 */
class IzhikevichNeuron {
private:
    double a, b, c, d; // Izhikevich parameters
    double v, u;       // v = membrane potential, u = recovery variable
    double current_input = 0.0;

    // Adjacency maps for scalable dynamic connectivity
    std::unordered_map<IzhikevichNeuron*, std::unique_ptr<Synapse>> outbound_synapses;
    std::vector<IzhikevichNeuron*> inbound_sources;

public:
    IzhikevichNeuron(double a = 0.02, double b = 0.2, double c = -65.0, double d = 8.0)
        : a(a), b(b), c(c), d(d), v(-65.0), u(b * -65.0) {}

    /**
     * @brief Dynamically connect as an output to a target neuron.
     */
    void connect_to(IzhikevichNeuron* target, double weight = 0.5) {
        if (!target) throw std::invalid_argument("Target neuron cannot be null.");
        if (outbound_synapses.find(target) == outbound_synapses.end()) {
            outbound_synapses[target] = std::make_unique<Synapse>(target, weight);
            target->register_source(this);
        }
    }

    /**
     * @brief Dynamically disconnect from a target neuron.
     */
    void disconnect_from(IzhikevichNeuron* target) {
        if (!target) return;
        if (outbound_synapses.erase(target)) {
            target->unregister_source(this);
        }
    }

    void register_source(IzhikevichNeuron* source) {
        inbound_sources.push_back(source);
    }

    void unregister_source(IzhikevichNeuron* source) {
        inbound_sources.erase(std::remove(inbound_sources.begin(), inbound_sources.end(), source), inbound_sources.end());
    }

    void receive_input(double i) { current_input += i; }

    /**
     * @brief Callback for STDP when a post-synaptic target fires.
     */
    void handle_post_spike(double t, IzhikevichNeuron* target) {
        if (outbound_synapses.count(target)) {
            outbound_synapses[target]->update_weight(t, false);
        }
    }

    /**
     * @brief Euler integration step for the neuron dynamics.
     */
    bool step(double t, double dt = 1.0) {
        bool fired = false;

        // Izhikevich differential equations
        v += dt * (0.04 * v * v + 5.0 * v + 140.0 - u + current_input);
        u += dt * (a * (b * v - u));
        current_input = 0.0;

        if (v >= 30.0) {
            fired = true;
            v = c;
            u += d;

            // Pre-synaptic update and signal propagation
            for (auto& entry : outbound_synapses) {
                entry.second->update_weight(t, true);
                entry.first->receive_input(entry.second->weight * 15.0);
            }
            // Post-synaptic update for incoming connections
            for (auto* src : inbound_sources) {
                src->handle_post_spike(t, this);
            }
        }
        return fired;
    }

    double get_weight(IzhikevichNeuron* target) {
        return outbound_synapses.count(target) ? outbound_synapses[target]->weight : 0.0;
    }
};

/**
 * @brief Example usage for building a primitive network.
 */
int main() {
    try {
        // Create two Regular Spiking neurons
        IzhikevichNeuron n1(0.02, 0.2, -65.0, 8.0);
        IzhikevichNeuron n2(0.02, 0.2, -65.0, 8.0);

        // Dynamic connection setup
        n1.connect_to(&n2, 0.5);

        std::cout << "Simulating primitive 2-neuron interaction...\n";
        for (int t = 0; t < 100; ++t) {
            n1.receive_input(15.0);
            if (n1.step(t)) std::cout << "t=" << t << ": N1 fired. Weight to N2: " << n1.get_weight(&n2) << "\n";
            if (n2.step(t)) std::cout << "t=" << t << ": N2 fired.\n";
        }

        n1.disconnect_from(&n2);
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
    }
    return 0;
}
```

### Biological Relevance

1.  **Dynamic Connectivity**: In primitive organisms, neural pathways can be plastic. The use of `std::unordered_map` and pointer management allows the network to simulate growth or synaptic pruning in real-time.
2.  **Izhikevich Efficiency**: This model is ideal for large-scale simulations because it captures various firing patterns (like those found in simple ganglia) with minimal computational overhead.
3.  **STDP Learning**: This mimics basic learning where connections strengthen if sensory input (pre-synaptic) consistently triggers a motor response (post-synaptic), allowing the simulated organism to adapt to its environment.

