```python
import firebase_admin
from firebase_admin import firestore

def process_final_signup(uid, data):
    """
    Finalizes the user profile by saving physical stats and 
    validating the data structure.

    :param uid: The Firebase Auth UID.
    :param data: Dictionary containing weight, height, body_type, and profile_pic_url.
    """
    db = firestore.client()

    try:
        # 1. Data Sanitization
        # Convert strings to floats for numerical queries later
        weight = float(data.get('weight', 0))
        height = float(data.get('height', 0))
        body_type = str(data.get('body_type', 'Not Specified'))
        pic_url = str(data.get('profile_pic_url', ''))

        # 2. Construct the profile object
        profile_update = {
            "weight": weight,
            "height": height,
            "bodyType": body_type,
            "profilePic": pic_url,
            "profileCompleted": True,
            "updatedAt": firestore.SERVER_TIMESTAMP
        }

        # 3. Update the user document in Firestore
        user_ref = db.collection('users').document(uid)
        user_ref.update(profile_update)

        return {"status": "success", "message": "Profile finalized"}

    except ValueError:
        return {"status": "error", "message": "Weight and Height must be numbers"}
    except Exception as e:
        return {"status": "error", "message": str(e)}
