    [Header("Physics Settings")]
    public Rigidbody2D rb;
    public float forceMultiplier = 5f;
    public int resolution = 30; 
    public float step = 0.1f;   

    [Header("UI & Layering Integration")]
    public string sortingLayerName = "UI"; 
    public int orderInLayer = 5;
    public Camera uiCamera;

    [Header("Visual Style (Dots)")]
    public float dotSize = 0.15f;
    public float tilingFactor = 20f; // Adjust to control dot density

    private LineRenderer lr;
    private Vector2 startPoint;
    private bool isDragging = false;

    void Awake()
    {
        lr = GetComponent<LineRenderer>();
        lr.enabled = false;

        // 1. Script-based "Dotted" Setup
        lr.useWorldSpace = true;
        lr.textureMode = LineTextureMode.Tile; // Required for dotted look
        lr.alignment = LineAlignment.View;    // Ensures dots face the UI camera
        lr.startWidth = dotSize;
        lr.endWidth = dotSize;

        // 2. Force the LineRenderer into the UI Sorting Hierarchy
        lr.sortingLayerName = sortingLayerName;
        lr.sortingOrder = orderInLayer;

        if (lr.material == null)
        {
            lr.material = new Material(Shader.Find("Sprites/Default"));
        }
        // Set initial tiling for the dots
        lr.material.mainTextureScale = new Vector2(tilingFactor, 1f);

        if (uiCamera == null) uiCamera = Camera.main;
    }

    void Update()
    {
        HandleInput();
    }

    private void HandleInput()
    {
        if (Input.GetMouseButtonDown(0))
        {
            if (IsPointerOverUI()) return;

            startPoint = uiCamera.ScreenToWorldPoint(Input.mousePosition);
            isDragging = true;
            lr.enabled = true;
        }

        if (isDragging && Input.GetMouseButton(0))
        {
            Vector2 currentMousePos = uiCamera.ScreenToWorldPoint(Input.mousePosition);
            Vector2 direction = startPoint - currentMousePos;
            DrawTrajectory(direction);
        }

        if (isDragging && Input.GetMouseButtonUp(0))
        {
            Vector2 endPoint = uiCamera.ScreenToWorldPoint(Input.mousePosition);
            Vector2 direction = startPoint - endPoint;

            Launch(direction);

            lr.enabled = false;
            isDragging = false;
        }
    }

    private bool IsPointerOverUI()
    {
        if (EventSystem.current == null) return false;
        if (EventSystem.current.IsPointerOverGameObject()) return true;
        if (Input.touchCount > 0 && EventSystem.current.IsPointerOverGameObject(Input.GetTouch(0).fingerId)) return true;
        return false;
    }

    void DrawTrajectory(Vector2 direction)
    {
        lr.positionCount = resolution;
        Vector2 velocity = direction * forceMultiplier;
        Vector3[] points = new Vector3[resolution];

        for (int i = 0; i < resolution; i++)
        {
            float t = i * step;
            Vector2 pos = (Vector2)transform.position + (velocity * t) + 0.5f * Physics2D.gravity * (t * t);
            // Match Z-depth to ensure it respects sorting layers in Screen Space - Camera
            points[i] = new Vector3(pos.x, pos.y, transform.position.z);
        }

        lr.SetPositions(points);
    }

    void Launch(Vector2 direction)
    {
        rb.velocity = direction * forceMultiplier;
    }
}
```

### Critical Setup for Seamless UI Integration

To ensure the trajectory appears correctly across all scenarios, follow these configuration steps:

1.  **Canvas Render Mode:** Your Canvas **must** be set to **Screen Space - Camera**. This allows the `LineRenderer` (which exists in the world) to be sorted against UI elements using standard Sorting Layers.
2.  **The "Sandwich" Technique:** 
    *   Create three Sorting Layers: `UI_Background`, `UI_Trajectory`, and `UI_Foreground`.
    *   Assign your UI background panels to `UI_Background`.
    *   Set the script's `sortingLayerName` to `UI_Trajectory`.
    *   Assign your buttons and HUD to `UI_Foreground`.
3.  **Material Setup:** In the Inspector, assign a Material to the `LineRenderer` that uses a **Circle Sprite** as its texture. Because the script sets the `Texture Mode` to **Tile**, this sprite will repeat along the path, creating the dotted effect.
4.  **Interaction Blocking:** The `IsPointerOverUI()` check prevents the trajectory from appearing when you click on buttons. Ensure your UI elements have **Raycast Target** enabled for this to work.

